276	    public List<Pet> getPets() {
277	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
278	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
279	        return Collections.unmodifiableList(sortedPets);
