253	    public boolean isHouseholdInUse(String householdId, Integer excludeId) throws DataAccessException {
254	        if (householdId == null) {
255	            return false;
256	        }
257	        for (Owner existing : ownerRepository.findAll()) {
258	            if (existing.isDeleted()) {
259	                continue;
260	            }
261	            if (excludeId != null && excludeId.equals(existing.getId())) {
262	                continue;
263	            }
264	            if (householdId.equals(existing.getHouseholdId())) {
265	                return true;
266	            }
267	        }
268	        return false;
269	    }
