592	    /**
593	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
594	     * containing at least one dot, none of the three sections containing whitespace or an
595	     * additional {@code @}.
596	     */
597	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
598	
599	    /**
600	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
601	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
602	     * case-insensitively against the domain (the part after the {@code @}).
603	     */
604	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
605	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
606	
607	    /**
608	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
609	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
610	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
611	     * lower-cased.
612	     *
613	     * @param email the raw email value supplied by the client, possibly {@code null}
614	     * @return the lower-cased email, or {@code null} when none was supplied
615	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
616	     *                                 is not a syntactically valid address, or its domain is on the
617	     *                                 disposable-domain blocklist
618	     */
619	    private static String normalizeEmail(String email) {
620	        if (email == null) {
621	            return null;
622	        }
623	        if (!EMAIL_PATTERN.matcher(email).matches()) {
624	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
625	                "email must be a syntactically valid address");
626	        }
627	        String normalized = email.toLowerCase(Locale.ROOT);
628	        String domain = normalized.substring(normalized.indexOf('@') + 1);
629	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
630	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
631	                "email domain " + domain + " is not allowed");
632	        }
633	        return normalized;
634	    }
