301	            return false;
302	        }
303	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
304	    }
305	
306	    /**
307	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
308	     */
309	    Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
311	
312	    /**
313	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
314	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
315	     * inclusive.
316	     */
317	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
318	        "NSW", new int[] {2000, 2099},
319	        "VIC", new int[] {3000, 3099},
320	        "QLD", new int[] {4000, 4099});
321	
322	    /**
323	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
324	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
325	     * region is baked into the customer code at creation (see the create endpoint), the locality now
326	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
327	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
328	     * {@link #regionOf(Owner)}.
329	     */
330	    default String toLocality(Owner owner) {
331	        String code = owner.getCustomerCode();
332	        if (code != null) {
333	            int dash = code.indexOf('-');
334	            if (dash > 0) {
335	                return code.substring(0, dash);
336	            }
337	        }
338	        return regionOf(owner);
339	    }
340	
341	    /**
342	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
343	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
344	     */
345	    Map<String, String> REGION_TIMEZONE = Map.of(
346	        "NSW", "Australia/Sydney",
347	        "VIC", "Australia/Melbourne",
348	        "QLD", "Australia/Brisbane");
349	
350	    /**
351	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
352	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
353	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
354	     */
355	    default String toTimezone(Owner owner) {
356	        return REGION_TIMEZONE.get(toLocality(owner));
357	    }
358	
359	    /**
360	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
361	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
362	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
363	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
364	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
365	     */
366	    default String regionOf(Owner owner) {
367	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
368	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
369	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
370	        String postcode = owner.getPostcode();
371	        if (postcode != null) {
372	            try {
373	                int value = Integer.parseInt(postcode.trim());
374	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
375	                    int[] range = entry.getValue();
376	                    if (value >= range[0] && value <= range[1]) {
377	                        return entry.getKey();
378	                    }
379	                }
380	            }
381	            catch (NumberFormatException ignored) {
382	                // Non-numeric postcode: fall back to the city table below.
383	            }
384	        }
385	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
386	    }
387	
388	    Owner toOwner(OwnerDto ownerDto);
389	
390	    @Mapping(target = "id", ignore = true)
391	    @Mapping(target = "pets", ignore = true)
392	    Owner toOwner(OwnerFieldsDto ownerDto);
393	
394	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
395	
396	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
397	
398	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
399	        OwnerPageDto ownerPageDto = new OwnerPageDto();
400	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
401	        ownerPageDto.setPage(ownerPage.getNumber());
402	        ownerPageDto.setSize(ownerPage.getSize());
403	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
404	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
405	        return ownerPageDto;
406	    }
407	}
