293	     * postcode. The value is deterministic (the first 12 upper-case hex characters of the SHA-256
294	     * digest of the normalized last name and the postcode, joined with {@code '|'}), so every owner
295	     * in the same household is assigned an identical identifier regardless of creation order and
296	     * without any explicit linking.
297	     *
298	     * @param lastName the owner's last name
299	     * @param postcode the owner's postcode, possibly {@code null}
300	     * @return the stable household identifier
301	     */
302	    private static String householdIdFor(String lastName, String postcode) {
303	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
304	        try {
305	            byte[] digest = MessageDigest.getInstance("SHA-256")
306	                .digest(key.getBytes(StandardCharsets.UTF_8));
307	            StringBuilder sb = new StringBuilder(digest.length * 2);
308	            for (byte b : digest) {
309	                sb.append(String.format("%02X", b));
310	            }
311	            return sb.substring(0, 12);
312	        } catch (NoSuchAlgorithmException ex) {
313	            throw new IllegalStateException("SHA-256 not available", ex);
314	        }
315	    }
