249	    @Override
250	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
251	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
252	        if (currentOwner != null) {
