265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
